    {"name": "edit", "arguments": {"path": "src/cache.js", "range": "6xm-77wi", "new": "// The cache. README.md has the contract.\n//\n// Entries live in a Map in least-to-most-recently-used order.\n\nexport class TtlCache {\n  constructor({ capacity, ttl = 0, clock = Date.now, onEvict } = {}) {\n    if (!Number.isInteger(capacity) || capacity <= 0) throw new RangeError('capacity must be a positive integer');\n    this._validateTtl(ttl);\n    this._capacity = capacity;\n    this._ttl = ttl;\n    this._clock = clock;\n    this._onEvict = onEvict;\n    this._entries = new Map();\n    this._stats = { hits: 0, misses: 0, expired: 0, evicted: 0 };\n  }\n\n  _validateTtl(ttl) {\n    if (typeof ttl !== 'number' || !Number.isFinite(ttl) || ttl < 0) throw new RangeError('ttl must be a finite nonnegative number');\n  }\n\n  _expiry(ttl) {\n    this._validateTtl(ttl);\n    return ttl === 0 ? Infinity : this._clock() + ttl;\n  }\n\n  _purgeExpired() {\n    const now = this._clock();\n    const expired = [];\n    for (const [key, entry] of this._entries) {\n      if (now >= entry.expires) {\n        this._entries.delete(key);\n        expired.push([key, entry.value]);\n      }\n    }\n    this._stats.expired += expired.length;\n    for (const [key, value] of expired) this._onEvict?.(key, value, 'expired');\n    return expired.length;\n  }\n\n  _start() { this._purgeExpired(); }\n\n  set(key, value, { ttl } = {}) {\n    this._start();\n    const life = ttl === undefined ? this._ttl : ttl;\n    const expires = this._expiry(life);\n    if (this._entries.has(key)) this._entries.delete(key);\n    else if (this._entries.size >= this._capacity) {\n      const [oldest, entry] = this._entries.entries().next().value;\n      this._entries.delete(oldest);\n      this._stats.evicted++;\n      this._onEvict?.(oldest, entry.value, 'capacity');\n    }\n    this._entries.set(key, { value, expires });\n    return this;\n  }\n\n  get(key) {\n    this._start();\n    const entry = this._entries.get(key);\n    if (!entry) { this._stats.misses++; return undefined; }\n    this._stats.hits++;\n    this._entries.delete(key);\n    this._entries.set(key, entry);\n    return entry.value;\n  }\n\n  peek(key) { this._start(); return this._entries.get(key)?.value; }\n\n  has(key) { this._start(); return this._entries.has(key); }\n\n  touch(key, { ttl } = {}) {\n    this._start();\n    const entry = this._entries.get(key);\n    if (!entry) return false;\n    const expires = this._expiry(ttl === undefined ? this._ttl : ttl);\n    this._entries.delete(key);\n    this._entries.set(key, { value: entry.value, expires });\n    return true;\n  }\n\n  delete(key) {\n    this._start();\n    const entry = this._entries.get(key);\n    if (!entry) return false;\n    this._entries.delete(key);\n    this._onEvict?.(key, entry.value, 'deleted');\n    return true;\n  }\n\n  clear() {\n    this._start();\n    const entries = [...this._entries];\n    this._entries.clear();\n    for (const [key, entry] of entries) this._onEvict?.(key, entry.value, 'cleared');\n  }\n\n  prune() { return this._purgeExpired(); }\n\n  get size() { this._start(); return this._entries.size; }\n\n  get stats() { this._start(); return { ...this._stats }; }\n\n  keys() { this._start(); return [...this._entries.keys()].reverse(); }\n}\n"}},
    {"name": "shell", "arguments": {"cmd": "node --input-type=module <<'EOF'\nimport assert from 'node:assert/strict';\nimport { TtlCache, manualClock } from './src/index.js';\nconst clock=manualClock(10), ev=[]; const c=new TtlCache({capacity:2,ttl:5,clock,onEvict:(...x)=>ev.push(x)});\nc.set('a',1).set('b',2,{ttl:0}); assert.deepEqual(c.keys(),['b','a']); assert.equal(c.peek('a'),1); assert.deepEqual(c.keys(),['b','a']);\nassert.equal(c.touch('a',{ttl:3}),true); assert.deepEqual(c.keys(),['a','b']); assert.equal(c.get('a'),1); assert.deepEqual(c.keys(),['a','b']);\nclock.advance(3); assert.equal(c.has('a'),false); assert.deepEqual(ev,[['a',1,'expired']]); assert.deepEqual(c.stats,{hits:1,misses:0,expired:1,evicted:0});\nc.set('c',3); c.delete('b'); assert.deepEqual(ev.at(-1),['b',2,'deleted']); c.clear(); assert.deepEqual(ev.at(-1),['c',3,'cleared']);\nassert.throws(()=>new TtlCache({capacity:0}),RangeError); assert.throws(()=>new TtlCache({capacity:1,ttl:Infinity}),RangeError);\nEOF", "expect_exit": "0"}},
